const KEY = "grcko_hrvatski_rjecnik_v3";
let entries = [];
let selectedId = null;
let currentLetter = "";

const $ = id => document.getElementById(id);
const search = $("search"), searchMode = $("searchMode");
const listEl = $("entryList"), lettersEl = $("letters"), countEl = $("count");
const welcome = $("welcome"), view = $("entryView"), editor = $("editor");

function loadLocalEntries(){
  try {
    const saved = localStorage.getItem(KEY);
    if(saved) return JSON.parse(saved);
  } catch(e) {}
  return SOURCE.map(x=>({...x}));
}
function save(){
  localStorage.setItem(KEY, JSON.stringify(entries));
  setSaveStatus("✓ Promjene spremljene na ovom uređaju.");
}
function norm(s){return (s||"").normalize("NFD").replace(/[\\u0300-\\u036f]/g,"").toLowerCase()}
function greekBase(s){
  return (s||"")
    .normalize("NFD")
    .replace(/[\\u0300-\\u036f\\u1ab0-\\u1aff\\u1dc0-\\u1dff\\u0483-\\u0489]/g,"")
    .replace(/[\\u0313\\u0314\\u0342\\u0343\\u0344\\u0345]/g,"")
    .toLowerCase();
}
function firstLetter(s){
  const n=greekBase(s).trim();
  if(!n) return "#";
  const ch=n[0];
  const map={
    "α":"Α","β":"Β","γ":"Γ","δ":"Δ","ε":"Ε","ζ":"Ζ","η":"Η","θ":"Θ",
    "ι":"Ι","κ":"Κ","λ":"Λ","μ":"Μ","ν":"Ν","ξ":"Ξ","ο":"Ο","π":"Π",
    "ρ":"Ρ","σ":"Σ","ς":"Σ","τ":"Τ","υ":"Υ","φ":"Φ","χ":"Χ","ψ":"Ψ","ω":"Ω"
  };
  return map[ch] || ch.toUpperCase();
}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

function filtered(){
  const q=norm(search.value.trim());
  return entries.filter(e=>{
    const letterOk=!currentLetter || firstLetter(e.lemma)===currentLetter;
    if(!letterOk) return false;
    if(!q) return true;
    const hay=searchMode.value==="lemma"?e.lemma:searchMode.value==="meaning"?e.text:e.text;
    return norm(hay).includes(q);
  });
}
function renderLetters(){
  const greekAlphabet=["Α","Β","Γ","Δ","Ε","Ζ","Η","Θ","Ι","Κ","Λ","Μ","Ν","Ξ","Ο","Π","Ρ","Σ","Τ","Υ","Φ","Χ","Ψ","Ω"];
  lettersEl.innerHTML=`<button data-letter="" class="${!currentLetter?'active':''}">SVE</button>`+
    greekAlphabet.map(l=>`<button data-letter="${esc(l)}" class="${currentLetter===l?'active':''}">${esc(l)}</button>`).join("");
  lettersEl.querySelectorAll("button").forEach(b=>b.onclick=()=>{
    currentLetter=b.dataset.letter;
    renderAll();
    if(currentLetter){
      requestAnimationFrame(()=>{
        const first=listEl.querySelector(".entry-row");
        if(first) first.scrollIntoView({behavior:"smooth",block:"start"});
      });
    }
  });
}
function renderList(){
  const list=filtered();
  countEl.textContent=list.length+" nat.";
  listEl.innerHTML=list.map(e=>`
    <div class="entry-row ${e.id===selectedId?'active':''}" data-id="${e.id}">
      <div class="lemma">${esc(e.lemma)}</div>
      <div class="preview">${esc(e.text)}</div>
    </div>`).join("");
  listEl.querySelectorAll(".entry-row").forEach(r=>r.onclick=()=>showEntry(Number(r.dataset.id)));
}
function renderAll(){ renderLetters(); renderList(); }

function showEntry(id){
  const e=entries.find(x=>x.id===id); if(!e)return;
  selectedId=id; welcome.classList.add("hidden"); editor.classList.add("hidden"); view.classList.remove("hidden");
  view.innerHTML=`
    <button class="mobile-back" id="backToList">← Natrag na natuknice</button>
    <div class="entry-meta">Natuknica</div>
    <h1 class="entry-title">${esc(e.lemma)}</h1>
    <div class="entry-body">${esc(e.text)}</div>
    <div class="entry-tools"><button id="editBtn">Uredi</button></div>`;
  $("editBtn").onclick=()=>openEditor(id);
  $("backToList").onclick=()=>{ view.classList.add("hidden"); selectedId=null; renderList(); };
  renderList();

  // Nakon odabira natuknice na mobitelu automatski prikaži otvoreni zapis.
  // Na računalu sadržaj ostaje u desnom stupcu pa nema potrebe za pomicanjem.
  requestAnimationFrame(()=>{
    if(window.matchMedia("(max-width: 800px)").matches){
      view.scrollIntoView({behavior:"smooth", block:"start"});
    }
  });
}
function openEditor(id=null){
  setSaveStatus("Uređivanje: promjene će se spremiti kad kliknete „Spremi“.");
  editor.classList.remove("hidden"); view.classList.add("hidden"); welcome.classList.add("hidden");
  const e=id?entries.find(x=>x.id===id):null;
  $("editorTitle").textContent=e?"Uredi natuknicu":"Nova natuknica";
  $("editLemma").value=e?.lemma||"";
  $("editText").value=e?.text||"";
  $("deleteEntry").style.display=e?"inline-block":"none";
  editor.dataset.id=id||"";
}
function closeEditor(){
  editor.classList.add("hidden");
  if(selectedId) showEntry(selectedId); else welcome.classList.remove("hidden");
}
function saveEditor(){
  const lemma=$("editLemma").value.trim(), text=$("editText").value.trim();
  if(!lemma||!text){alert("Upišite natuknicu i tekst unosa.");return}
  const id=Number(editor.dataset.id);
  if(id){
    const e=entries.find(x=>x.id===id); e.lemma=lemma; e.text=text;
  }else{
    const newId=entries.length?Math.max(...entries.map(x=>Number(x.id)||0))+1:1;
    entries.push({id:newId,lemma,text});
    selectedId=newId;
  }
  save(); renderLetters(); renderList(); showEntry(selectedId);
}
function deleteEditor(){
  const id=Number(editor.dataset.id); if(!id)return;
  const entry=entries.find(x=>x.id===id);
  if(!confirm(`Obrisati natuknicu „${entry?.lemma||""}“? Ova radnja se može vratiti samo ako imate izvezeni sigurnosni primjerak.`))return;
  entries=entries.filter(x=>x.id!==id); save(); selectedId=null;
  editor.classList.add("hidden"); view.classList.add("hidden"); welcome.classList.remove("hidden");
  renderLetters(); renderList();
}
$("newEntry").onclick=()=>openEditor();
$("closeEditor").onclick=closeEditor;
$("saveEntry").onclick=saveEditor;
$("deleteEntry").onclick=deleteEditor;
search.oninput=renderList;
searchMode.onchange=renderList;
$("clearSearch").onclick=()=>{search.value="";renderList();search.focus()};
function exportDictionary(){
  const blob=new Blob([JSON.stringify(entries,null,2)],{type:"application/json"});
  const a=document.createElement("a");
  a.href=URL.createObjectURL(blob);
  a.download="rjecnik.json";
  a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),500);
}
$("exportBtn").onclick=exportDictionary;
$("publishBtn").onclick=()=>{
  exportDictionary();
  setSaveStatus("✓ Datoteka rjecnik.json pripremljena za objavu.");
  alert(
    "Datoteka rjecnik.json je preuzeta.\n\n" +
    "Da bi se promjene pojavile na javnom rječniku:\n" +
    "1. Otvorite GitHub repository.\n" +
    "2. Otvorite mapu data.\n" +
    "3. Odaberite rjecnik.json i učitajte novu datoteku na njegovo mjesto.\n" +
    "4. Potvrdite Commit changes.\n\n" +
    "Ostale datoteke ne treba mijenjati."
  );
};
$("importBtn").onclick=()=>$("fileInput").click();
$("fileInput").onchange=async e=>{
  const file=e.target.files[0]; if(!file)return;
  try{
    const imported=JSON.parse(await file.text());
    if(!Array.isArray(imported))throw Error();
    entries=imported.map((x,i)=>({id:x.id??i+1,lemma:String(x.lemma??""),text:String(x.text??"")}));
    save(); selectedId=null; renderLetters(); renderList();
    setSaveStatus("✓ Uvezeni rječnik spremljen na ovom uređaju.");
    alert("Rječnik je uvezen.");
  }catch(err){alert("Datoteka nije valjani JSON rječnik.")}
  e.target.value="";
};
$("themeBtn").onclick=()=>document.body.classList.toggle("dark");

async function boot(){
  if(location.protocol === "http:" || location.protocol === "https:"){
    try{
      const controller = new AbortController();
      const timer = setTimeout(()=>controller.abort(),5000);
      const url = new URL("rjecnik.json", location.href);
      url.searchParams.set("v", Date.now().toString());
      const response = await fetch(url.toString(), {cache:"no-store", signal:controller.signal});
      clearTimeout(timer);
      if(!response.ok) throw new Error("HTTP "+response.status);
      const imported = await response.json();
      if(!Array.isArray(imported)) throw new Error("Neispravan rječnik");
      entries = imported.map((x,i)=>({id:x.id??i+1,lemma:String(x.lemma??""),text:String(x.text??"")}));
    }catch(e){
      entries = SOURCE.map(x=>({...x}));
    }
  }else{
    entries = loadLocalEntries();
  }
  renderLetters(); renderList();
}
boot();
